from time import time
from threading import Lock, Condition
from six.moves import queue

from .listener import InfoModelChangeListener
from .event import ResetEvent, RemoveEvent, UpdateEvent
from .event.factory import EventMatcherFactory

from .exception import InfoModelTimeoutException, InfoModelDumpNotFoundException, InfoModelConnectionException


def condition_lock(function):
    """Handle condition lock."""

    def _wrap(inst, *args, **kw):
        inst.lock.acquire()
        try:
            return function(inst, *args, **kw)
        finally:
            inst.lock.release()

    return _wrap


class InfoModelChangeMonitor(InfoModelChangeListener):

    def __init__(self, queue_maxsize=0):
        self.lock = Lock()
        self.im_dump = {}
        self.event_queue = queue.Queue(maxsize=queue_maxsize)
        self.factory = EventMatcherFactory()

    @condition_lock
    def on_reset(self, timestamp):
        """Called when connection reset."""
        self.im_dump = {}
        self.event_queue.put(ResetEvent(timestamp))

    @condition_lock
    def on_remove(self, removed, timestamp):
        """Called when infomodel object is removed."""
        for dist_name in removed:
            if dist_name in self.im_dump:
                del self.im_dump[dist_name]
        self.event_queue.put(RemoveEvent(removed, timestamp))

    @condition_lock
    def on_update(self, updated, timestamp):
        """Called when infomodel object changes."""
        self.im_dump.update(updated)
        self.event_queue.put(UpdateEvent(updated, timestamp))

    def get_infomodel_dump(self, timeout):
        """Get InfoModel dump."""
        try:
            self.wait_for_any_action(timeout)
        except InfoModelTimeoutException:
            if not self.im_dump:
                raise InfoModelDumpNotFoundException('InfoModel dump not found.')
        return self._get_im_dump_items()

    def wait_for_event(self, event_description, timeout):
        """Wait for specified event."""
        event_matcher = self.factory.create_event_matcher(event_description, self._get_im_dump_copy())
        return self._wait_until_satisfied(event_matcher, timeout)

    def wait_for_any_action(self, timeout):
        """Wait for any action."""
        event_matcher = self.factory.create_any_event_matcher()
        return self._wait_until_satisfied(event_matcher, timeout)

    def wait_for_change(self, timeout):
        """"Wait for onChange action."""
        event_matcher = self.factory.create_any_change_matcher()
        return self._wait_until_satisfied(event_matcher, timeout)

    def wait_for_reset(self, timeout):
        """Wait for onReset action."""
        event_matcher = self.factory.create_reset_matcher()
        return self._wait_until_satisfied(event_matcher, timeout)

    def _wait_until_satisfied(self, event_matcher, timeout):
        start_time = time()
        while time() - start_time <= timeout:
            time_left = timeout - (time() - start_time)
            if event_matcher.match(self._get_event(time_left)) and event_matcher.satisfied():
                break

        if event_matcher.satisfied():
            return event_matcher.get_timestamp()
        raise InfoModelTimeoutException("Expected: %s not registered in InfoModel." % event_matcher)

    def _get_event(self, timeout):
        timeout = 0 if timeout < 0 else timeout
        try:
            return self.event_queue.get(block=True, timeout=timeout)
        except queue.Empty:
            return None

    @condition_lock
    def _get_im_dump_items(self):
        return list(self.im_dump.items())

    @condition_lock
    def _get_im_dump_copy(self):
        return self.im_dump.copy()


class InfoModelConnectionMonitor(object):

    OPENED = "Admin API connection opened but not connected to InfoModel."
    CONNECTED = "Connected to InfoModel."
    RECONNECTING = "Reconnecting after reset."

    def __init__(self):
        self.lock = Condition()
        self.current_status = None
        self.expected_status = None

    def on_connection_status_change(self, status):
        """Called when connection status changes."""
        self._notify(str(status))

    def on_open(self):
        """Called when connection reset."""
        self._notify(self.OPENED)

    def on_reset(self):
        """Called when connection reset."""
        self._notify(self.RECONNECTING)

    def on_update(self):
        """Called when infomodel object changes."""
        self._notify(self.CONNECTED)

    @condition_lock
    def _notify(self, status):
        self.current_status = status
        self.lock.notify()

    @condition_lock
    def wait_until_connected_to_infomodel(self, timeout=0):
        """Wait util connection status is registered to InfoModel."""
        start_time = time()
        while not self.is_connected_to_infomodel() and time() - start_time <= timeout:
            self.lock.wait(timeout - (time() - start_time))

        if self.is_connected_to_infomodel():
            return True
        raise InfoModelConnectionException('Expected connection status: Connected not achieved. Status reached: %s' % self.current_status)

    def is_connected_to_infomodel(self):
        """Check if status is registered to InfoModel."""
        return self.current_status == self.CONNECTED
